EquipmentEvent? _decodeEquipmentEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'PropertyChanged':
    case 'AutofocusProgress':
    case 'FocuserBacklashCalibrationProgress':
      return decodeEquipmentEventPropertyChanged(type, d, severity);
    case 'Connecting':
      return EquipmentEvent.connecting(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
        deviceName: wireString(d, 'device_name'),
      );
    case 'Connected':
      return EquipmentEvent.connected(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
        deviceName: wireString(d, 'device_name'),
      );
    case 'Disconnected':
      return EquipmentEvent.disconnected(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
      );
    case 'Error':
      return EquipmentEvent.error(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
        message: wireString(d, 'message'),
      );
    case 'MountSlewStarted':
      return EquipmentEvent.mountSlewStarted(
        deviceId: wireString(d, 'device_id'),
        ra: wireDouble(d, 'ra'),
        dec: wireDouble(d, 'dec'),
      );
    case 'MountSlewCompleted':
      return EquipmentEvent.mountSlewCompleted(
        deviceId: wireString(d, 'device_id'),
        ra: wireDouble(d, 'ra'),
        dec: wireDouble(d, 'dec'),
      );
    case 'MountTrackingStarted':
      return EquipmentEvent.mountTrackingStarted(
        deviceId: wireString(d, 'device_id'),
      );
    case 'MountTrackingStopped':
      return EquipmentEvent.mountTrackingStopped(
        deviceId: wireString(d, 'device_id'),
