    case 'FocuserMoveStarted':
      return EquipmentEvent.focuserMoveStarted(
        deviceId: wireString(d, 'device_id'),
        targetPosition: wireInt(d, 'target_position'),
      );
    case 'FocuserMoveCompleted':
