    case 'FilterChanged':
      return EquipmentEvent.filterChanged(
        deviceId: wireString(d, 'device_id'),
        position: wireInt(d, 'position'),
        filterName: wireOptString(d, 'filter_name'),
      );
    case 'RotatorMoveStarted':
      return EquipmentEvent.rotatorMoveStarted(
        deviceId: wireString(d, 'device_id'),
        targetAngle: wireDouble(d, 'target_angle'),
      );
    case 'RotatorMoveCompleted':
      return EquipmentEvent.rotatorMoveCompleted(
        deviceId: wireString(d, 'device_id'),
        angle: wireDouble(d, 'angle'),
      );
    case 'CameraCoolingStarted':
      return EquipmentEvent.cameraCoolingStarted(
        deviceId: wireString(d, 'device_id'),
        targetTemp: wireDouble(d, 'target_temp'),
      );
    case 'CameraCoolingReached':
      return EquipmentEvent.cameraCoolingReached(
        deviceId: wireString(d, 'device_id'),
        temperature: wireDouble(d, 'temperature'),
      );
    case 'CameraWarmingStarted':
      return EquipmentEvent.cameraWarmingStarted(
        deviceId: wireString(d, 'device_id'),
      );
    case 'CameraWarmingCompleted':
      return EquipmentEvent.cameraWarmingCompleted(
        deviceId: wireString(d, 'device_id'),
      );
    case 'CameraTemperatureChanged':
      return EquipmentEvent.cameraTemperatureChanged(
        deviceId: wireString(d, 'device_id'),
        temperature: wireDouble(d, 'temperature'),
        coolerPower: wireOptDouble(d, 'coolerPower'),
