    case 'HeartbeatStarted':
      return EquipmentEvent.heartbeatStarted(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
        intervalSecs: wireBigInt(d, 'interval_secs'),
