    case 'HeartbeatStatusChanged':
      return EquipmentEvent.heartbeatStatusChanged(
        deviceType: wireString(d, 'device_type'),
        deviceId: wireString(d, 'device_id'),
        status: wireRequired(decodeHeartbeatStatus(d['status']), 'status'),
        consecutiveFailures: wireInt(d, 'consecutive_failures'),
        lastRttMs: wireOptBigInt(d, 'last_rtt_ms'),
