    case 'DeviceLost':
      return EquipmentEvent.deviceLost(
        deviceClass: wireString(d, 'device_class'),
        driver: wireString(d, 'driver'),
        id: wireString(d, 'id'),
      );
  }
  return null;
}

WireEvent _encodeImagingEvent(ImagingEvent event) => switch (event) {
  ImagingEvent_ExposureStarted() => (
    'ExposureStarted',
    <String, Object?>{
      'duration_secs': event.durationSecs,
      'frame_type': encodeFrameType(event.frameType),
    },
  ),
  ImagingEvent_ExposureStartedWithFrame() => (
    'ExposureStarted',
    <String, Object?>{
      'duration_secs': event.durationSecs,
      'frame_type': encodeFrameType(event.frameType),
      'frame': event.frameNumber,
      'total': event.totalFrames,
    },
  ),
  ImagingEvent_ExposureProgress() => (
    'ExposureProgress',
    <String, Object?>{
      'progress': event.progress,
      'remainingSecs': event.remainingSecs,
    },
  ),
  ImagingEvent_ExposureCompleted() => (
    'ExposureCompleted',
    <String, Object?>{
      'file_path': event.filePath,
      'hfr': event.hfr,
      'stars_detected': event.starsDetected,
    },
  ),
  ImagingEvent_ExposureCompletedWithFrame() => (
    'ExposureCompleted',
    <String, Object?>{
      'frame': event.frameNumber,
      'total': event.totalFrames,
      'hfr': event.hfr,
      'stars_detected': event.starsDetected,
    },
  ),
  ImagingEvent_ExposureFailed() => (
    'ExposureFailed',
    <String, Object?>{'error': event.error},
  ),
  ImagingEvent_ExposureCancelled() => (
    'ExposureCancelled',
    <String, Object?>{},
  ),
  ImagingEvent_DownloadStarted() => ('DownloadStarted', <String, Object?>{}),
  ImagingEvent_DownloadCompleted() => (
    'DownloadCompleted',
    <String, Object?>{},
  ),
  ImagingEvent_ImageReady() => (
    'ImageReady',
    <String, Object?>{'width': event.width, 'height': event.height},
  ),
  ImagingEvent_ImageSaved() => (
    'ImageSaved',
    <String, Object?>{'file_path': event.filePath},
  ),
  ImagingEvent_IntegrationProgress() => (
    'IntegrationProgress',
    <String, Object?>{
      'phase': event.phase,
      'fraction': event.fraction,
      if (event.framesDone != null) 'frames_done': event.framesDone,
      if (event.framesTotal != null) 'frames_total': event.framesTotal,
    },
  ),
  ImagingEvent_IntegrationTelemetry() => encodeImagingEventIntegrationTelemetry(
    event,
  ),
  ImagingEvent_TemperatureChanged() => (
    'TemperatureChanged',
    <String, Object?>{
      'temp_celsius': event.tempCelsius,
      'cooler_power': event.coolerPower,
    },
  ),
  ImagingEvent_ExposureComplete() => (
    'ExposureComplete',
    <String, Object?>{'success': event.success},
  ),
  ImagingEvent_ExposureFailedOld() => (
    'ExposureFailed',
    <String, Object?>{'reason': event.reason},
  ),
};

ImagingEvent? _decodeImagingEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'IntegrationTelemetry':
      return decodeImagingEventIntegrationTelemetry(type, d, severity);
    case 'ExposureStarted':
      if (d['frame'] != null) {
        return ImagingEvent.exposureStartedWithFrame(
          durationSecs: wireDouble(d, 'duration_secs'),
          frameType: wireRequired(
            decodeFrameType(d['frame_type']),
            'frame_type',
          ),
          frameNumber: wireInt(d, 'frame'),
          totalFrames: wireOptInt(d, 'total'),
        );
      }
      return ImagingEvent.exposureStarted(
        durationSecs: wireDouble(d, 'duration_secs'),
        frameType: wireRequired(decodeFrameType(d['frame_type']), 'frame_type'),
      );
    case 'ExposureProgress':
      return ImagingEvent.exposureProgress(
        progress: wireDouble(d, 'progress'),
        remainingSecs: wireDouble(d, 'remainingSecs'),
      );
    case 'ExposureCompleted':
      if (d['frame'] != null) {
        return ImagingEvent.exposureCompletedWithFrame(
          frameNumber: wireInt(d, 'frame'),
          totalFrames: wireOptInt(d, 'total'),
          hfr: wireDouble(d, 'hfr'),
          starsDetected: wireInt(d, 'stars_detected'),
        );
      }
      return ImagingEvent.exposureCompleted(
        filePath: wireOptString(d, 'file_path'),
        hfr: wireDouble(d, 'hfr'),
        starsDetected: wireInt(d, 'stars_detected'),
      );
    case 'ExposureFailed':
      if (d['reason'] != null) {
        return ImagingEvent.exposureFailedOld(reason: wireString(d, 'reason'));
      }
      return ImagingEvent.exposureFailed(error: wireString(d, 'error'));
    case 'ExposureCancelled':
      return const ImagingEvent.exposureCancelled();
    case 'DownloadStarted':
      return const ImagingEvent.downloadStarted();
    case 'DownloadCompleted':
      return const ImagingEvent.downloadCompleted();
    case 'ImageReady':
      return ImagingEvent.imageReady(
        width: wireInt(d, 'width'),
        height: wireInt(d, 'height'),
      );
    case 'ImageSaved':
      return ImagingEvent.imageSaved(filePath: wireString(d, 'file_path'));
    case 'IntegrationProgress':
      return ImagingEvent.integrationProgress(
        phase: wireString(d, 'phase'),
        fraction: wireDouble(d, 'fraction'),
        framesDone: wireOptInt(d, 'frames_done'),
        framesTotal: wireOptInt(d, 'frames_total'),
      );
    case 'TemperatureChanged':
      return ImagingEvent.temperatureChanged(
        tempCelsius: wireDouble(d, 'temp_celsius'),
        coolerPower: wireDouble(d, 'cooler_power'),
      );
    case 'ExposureComplete':
      return ImagingEvent.exposureComplete(success: wireBool(d, 'success'));
  }
  return null;
}

