  GuidingEvent_GuidingStopped() => ('GuidingStopped', <String, Object?>{}),
  GuidingEvent_Paused() => ('Paused', <String, Object?>{}),
  GuidingEvent_Resumed() => ('Resumed', <String, Object?>{}),
  GuidingEvent_Settled() => ('SettleDone', <String, Object?>{'rms': event.rms}),
  GuidingEvent_LostStar() => ('StarLost', <String, Object?>{}),
  GuidingEvent_SettleTimedOut() => (
    'SettleTimedOut',
    <String, Object?>{'error': event.error},
  ),
  GuidingEvent_StopReason() => (
    'StopReason',
    <String, Object?>{'reason': event.reason},
  ),
  GuidingEvent_DitherStarted() => (
    'DitherStarted',
    <String, Object?>{'pixels': event.pixels},
  ),
  GuidingEvent_DitherCompleted() => ('DitherCompleted', <String, Object?>{}),
  GuidingEvent_Correction() => (
    'GuideStep',
    <String, Object?>{
      'RADistance': event.ra,
      'DECDistance': event.dec,
      'RADistanceRaw': event.raRaw,
      'DECDistanceRaw': event.decRaw,
    },
  ),
  GuidingEvent_Looping() => ('LoopingExposures', <String, Object?>{}),
  GuidingEvent_Settling() => ('Settling', <String, Object?>{}),
  GuidingEvent_Calibrating() => ('Calibrating', <String, Object?>{}),
  GuidingEvent_CalibrationComplete() => (
    'CalibrationComplete',
    <String, Object?>{},
  ),
  GuidingEvent_StarSelected() => (
    'StarSelected',
    <String, Object?>{'X': event.x, 'Y': event.y},
  ),
  GuidingEvent_AppState() => (
    'AppState',
    <String, Object?>{'State': event.state},
  ),
  GuidingEvent_GuideStats() => (
    'GuideStats',
    <String, Object?>{'SNR': event.snr, 'StarMass': event.starMass},
  ),
};

GuidingEvent? _decodeGuidingEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'Connected':
      return const GuidingEvent.connected();
    case 'Disconnected':
      return const GuidingEvent.disconnected();
    case 'GuidingStarted':
      return const GuidingEvent.guidingStarted();
    case 'GuidingStopped':
      return const GuidingEvent.guidingStopped();
    case 'Paused':
      return const GuidingEvent.paused();
    case 'Resumed':
      return const GuidingEvent.resumed();
    case 'SettleDone':
      return GuidingEvent.settled(rms: wireDouble(d, 'rms'));
    case 'StarLost':
      return const GuidingEvent.lostStar();
    case 'SettleTimedOut':
      return GuidingEvent.settleTimedOut(error: wireString(d, 'error'));
    case 'StopReason':
      return GuidingEvent.stopReason(reason: wireOptString(d, 'reason'));
    case 'DitherStarted':
      return GuidingEvent.ditherStarted(pixels: wireDouble(d, 'pixels'));
    case 'DitherCompleted':
      return const GuidingEvent.ditherCompleted();
    case 'GuideStep':
      return GuidingEvent.correction(
        ra: wireDouble(d, 'RADistance'),
        dec: wireDouble(d, 'DECDistance'),
        raRaw: wireRequired(wireOptDouble(d, 'RADistanceRaw'), 'RADistanceRaw'),
        decRaw: wireRequired(
          wireOptDouble(d, 'DECDistanceRaw'),
          'DECDistanceRaw',
        ),
      );
    case 'LoopingExposures':
      return const GuidingEvent.looping();
    case 'Settling':
      return const GuidingEvent.settling();
    case 'Calibrating':
      return const GuidingEvent.calibrating();
    case 'CalibrationComplete':
      return const GuidingEvent.calibrationComplete();
    case 'StarSelected':
      return GuidingEvent.starSelected(
        x: wireDouble(d, 'X'),
        y: wireDouble(d, 'Y'),
      );
    case 'AppState':
      return GuidingEvent.appState(state: wireString(d, 'State'));
    case 'GuideStats':
      return GuidingEvent.guideStats(
        snr: wireDouble(d, 'SNR'),
        starMass: wireDouble(d, 'StarMass'),
      );
  }
  return null;
}

WireEvent _encodeSequencerEvent(SequencerEvent event) => switch (event) {
  SequencerEvent_Started() => (
    'Started',
    <String, Object?>{'sequence_name': event.sequenceName},
  ),
  SequencerEvent_Paused() => ('Paused', <String, Object?>{}),
  SequencerEvent_Resumed() => ('Resumed', <String, Object?>{}),
  SequencerEvent_Stopped() => (
    'Stopped',
    <String, Object?>{
      if (event.sequenceRunId != null) 'sequence_run_id': event.sequenceRunId,
    },
  ),
  SequencerEvent_Completed() => ('Completed', <String, Object?>{}),
  SequencerEvent_Failed() => (
    'SequenceFailed',
    <String, Object?>{'error': event.error},
  ),
  SequencerEvent_NodeStarted() => (
    'NodeStarted',
    <String, Object?>{'node_id': event.nodeId, 'node_type': event.nodeType},
  ),
  SequencerEvent_NodeCompleted() => (
    'NodeCompleted',
    <String, Object?>{'node_id': event.nodeId, 'status': event.status},
  ),
  SequencerEvent_Progress() => (
    'Progress',
    <String, Object?>{'current': event.current, 'total': event.total},
  ),
  SequencerEvent_TargetChanged() => (
    'TargetChanged',
    <String, Object?>{
      'target_name': event.targetName,
      'ra': event.ra,
      'dec': event.dec,
    },
  ),
  SequencerEvent_TargetCompleted() => (
    'TargetCompleted',
    <String, Object?>{'target_name': event.targetName},
  ),
  SequencerEvent_ExposureStarted() => (
    'ExposureStarted',
    <String, Object?>{
      'frame': event.frame,
      'total': event.total,
      'filter': event.filter,
      'duration_secs': event.durationSecs,
    },
  ),
  SequencerEvent_ExposureCompleted() => (
    'ExposureCompleted',
    <String, Object?>{
      'frame': event.frame,
      'total': event.total,
      'duration_secs': event.durationSecs,
    },
  ),
  SequencerEvent_Error() => encodeSequencerEventError(event),
  SequencerEvent_MeridianFlipOutcome() => (
    'MeridianFlipOutcome',
    <String, Object?>{
      'outcome': encodeFlipOutcome(event.outcome),
      'target_name': event.targetName,
      'new_pier_side': event.newPierSide,
      'duration_secs': event.durationSecs,
      'attempts': event.attempts,
      'failed_steps': event.failedSteps,
      'error': event.error,
      'action_taken': event.actionTaken,
    },
  ),
  SequencerEvent_TriggerFired() => (
    'TriggerFired',
    <String, Object?>{
      'trigger_id': event.triggerId,
      'trigger_name': event.triggerName,
      'action': encodeSequencerTriggerAction(event.action),
    },
  ),
  SequencerEvent_InstructionProgress() => (
    'InstructionProgress',
    <String, Object?>{
      'node_id': event.nodeId,
      'instruction': event.instruction,
      'progress_percent': event.progressPercent,
      'detail': event.detail,
    },
  ),
  SequencerEvent_InstructionProgressStructured() => (
    'InstructionProgressStructured',
    <String, Object?>{
      'node_id': event.nodeId,
      'instruction': event.instruction,
      'progress_percent': event.progressPercent,
      'detail_kind': event.detailKind,
      'detail_json': event.detailJson,
    },
  ),
  SequencerEvent_DepthGoalCompleted() => (
    'DepthGoalCompleted',
    <String, Object?>{
      'node_id': event.nodeId,
      'filter_name': event.filterName,
      'goal_id': event.goalId,
      'revision': event.revision.toInt(),
      'evidence_frames': event.evidenceFrames,
      'confirmation_frames': event.confirmationFrames,
      'score': event.score,
      'threshold': event.threshold,
    },
  ),
  SequencerEvent_FrameAccepted() => (
    'FrameAccepted',
    <String, Object?>{
      'node_id': event.nodeId,
      'frame': event.frame,
      'total': event.total,
      'hfr': event.hfr,
      'eccentricity': event.eccentricity,
      'star_count': event.starCount,
      'accepted_total': event.acceptedTotal,
      'rejected_total': event.rejectedTotal,
      'save_path': event.savePath,
      ...encodeFrameCaptureMetadata(event.capture),
    },
  ),
  SequencerEvent_FrameRejected() => (
    'FrameRejected',
    <String, Object?>{
      'node_id': event.nodeId,
      'frame': event.frame,
      'total': event.total,
      'reason': event.reason,
      'hfr': event.hfr,
      'eccentricity': event.eccentricity,
