      'accepted_total': event.acceptedTotal,
      'rejected_total': event.rejectedTotal,
      'likely_cause_label': event.likelyCauseLabel,
      'evidence': event.evidence,
      'sky_brightness_at_capture': event.skyBrightnessAtCapture,
      'cloud_cover_at_capture': event.cloudCoverAtCapture,
      'wind_at_capture': event.windAtCapture,
      'guide_rms_at_capture': event.guideRmsAtCapture,
      'sensor_temp_at_capture': event.sensorTempAtCapture,
      ...encodeFrameCaptureMetadata(event.capture),
    },
  ),
  SequencerEvent_SchedulerDecision() => (
    'SchedulerDecision',
    <String, Object?>{
      'node_id': event.nodeId,
      'decision_counter': event.decisionCounter,
      'picked_target_id': event.pickedTargetId,
      'picked_target_name': event.pickedTargetName,
      'picked_score': event.pickedScore,
      'scores': event.scores.map(encodeSchedulerScoreEntry).toList(),
    },
  ),
  SequencerEvent_IntegrationBudget() => (
    'IntegrationBudget',
    <String, Object?>{
      'target_id': event.targetId,
      'filter': event.filter,
      'completed_secs': event.completedSecs,
      'budget_secs': event.budgetSecs,
      'fraction': event.fraction,
      'budget_met': event.budgetMet,
    },
  ),
  SequencerEvent_ExposureAdjusted() => (
    'ExposureAdjusted',
    <String, Object?>{
      'node_id': event.nodeId,
      'adapted_secs': event.adaptedSecs,
      'nominal_secs': event.nominalSecs,
      'sky_brightness_mag': event.skyBrightnessMag,
      'filter': event.filter,
      'reason': event.reason,
    },
  ),
  SequencerEvent_PhotometryFrame() => (
    'PhotometryFrame',
    <String, Object?>{
      'node_id': event.nodeId,
      'target_designation': event.targetDesignation,
      'reference_stars': event.referenceStars,
      'frame': event.frame,
      'total': event.total,
      'filter': event.filter,
      'exposure_secs': event.exposureSecs,
      'airmass': event.airmass,
      'fwhm_arcsec': event.fwhmArcsec,
      'snr': event.snr,
      'mjd_obs': event.mjdObs,
      'frame_start_unix': event.frameStartUnix,
      'accepted': event.accepted,
      'reject_reason': event.rejectReason,
      'reduce_live': event.reduceLive,
      'apply_differential': event.applyDifferential,
    },
  ),
  SequencerEvent_PhotometryCadenceBroken() => (
    'PhotometryCadenceBroken',
    <String, Object?>{
      'node_id': event.nodeId,
      'frame': event.frame,
      'total': event.total,
      'gap_secs': event.gapSecs,
      'max_gap_secs': event.maxGapSecs,
      'cadence_breaks': event.cadenceBreaks,
    },
  ),
  SequencerEvent_PhotometrySummary() => (
    'PhotometrySummary',
    <String, Object?>{
      'node_id': event.nodeId,
      'target_designation': event.targetDesignation,
      'filter': event.filter,
      'frames_captured': event.framesCaptured,
      'cadence_breaks': event.cadenceBreaks,
      'last_reject_reason': event.lastRejectReason,
    },
  ),
  SequencerEvent_RecoveryStarted() => (
    'RecoveryStarted',
    <String, Object?>{
      'started_at_iso': event.startedAtIso,
      'cause_kind': event.causeKind,
      'cause_custom_label': event.causeCustomLabel,
      'last_attempt_at_iso': event.lastAttemptAtIso,
      'attempt_count': event.attemptCount,
      'max_attempts': event.maxAttempts,
      'retry_interval_secs': event.retryIntervalSecs,
      'max_duration_secs': event.maxDurationSecs,
      'phase': event.phase,
      'last_error': event.lastError,
    },
  ),
  SequencerEvent_RecoveryProgress() => (
    'RecoveryProgress',
    <String, Object?>{
      'started_at_iso': event.startedAtIso,
      'cause_kind': event.causeKind,
      'cause_custom_label': event.causeCustomLabel,
      'last_attempt_at_iso': event.lastAttemptAtIso,
      'attempt_count': event.attemptCount,
      'max_attempts': event.maxAttempts,
