      'max_duration_secs': event.maxDurationSecs,
      'phase': event.phase,
      'last_error': event.lastError,
    },
  ),
  SequencerEvent_RecoveryCompleted() => (
    'RecoveryCompleted',
    <String, Object?>{
      'started_at_iso': event.startedAtIso,
      'cause_kind': event.causeKind,
      'cause_custom_label': event.causeCustomLabel,
      'last_attempt_at_iso': event.lastAttemptAtIso,
      'attempt_count': event.attemptCount,
      'max_attempts': event.maxAttempts,
      'retry_interval_secs': event.retryIntervalSecs,
      'max_duration_secs': event.maxDurationSecs,
