  SequencerEvent_DecisionLogged() => encodeSequencerEventDecisionLogged(event),
};

SequencerEvent? _decodeSequencerEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'Error':
      return decodeSequencerEventError(type, d, severity);
    case 'DecisionLogged':
      return decodeSequencerEventDecisionLogged(type, d, severity);
    case 'Started':
      return SequencerEvent.started(
        sequenceName: wireString(d, 'sequence_name'),
      );
    case 'Paused':
      return const SequencerEvent.paused();
    case 'Resumed':
      return const SequencerEvent.resumed();
    case 'Stopped':
      return SequencerEvent.stopped(
        sequenceRunId: wireOptInt(d, 'sequence_run_id'),
      );
    case 'Completed':
      return const SequencerEvent.completed();
    case 'SequenceFailed':
      return SequencerEvent.failed(error: wireString(d, 'error'));
    case 'NodeStarted':
      return SequencerEvent.nodeStarted(
        nodeId: wireString(d, 'node_id'),
        nodeType: wireString(d, 'node_type'),
      );
    case 'NodeCompleted':
      return SequencerEvent.nodeCompleted(
        nodeId: wireString(d, 'node_id'),
        status: wireString(d, 'status'),
      );
    case 'Progress':
      return SequencerEvent.progress(
        current: wireInt(d, 'current'),
        total: wireInt(d, 'total'),
      );
    case 'TargetChanged':
      return SequencerEvent.targetChanged(
        targetName: wireString(d, 'target_name'),
        ra: wireOptDouble(d, 'ra'),
        dec: wireOptDouble(d, 'dec'),
      );
    case 'TargetCompleted':
      return SequencerEvent.targetCompleted(
        targetName: wireString(d, 'target_name'),
      );
    case 'ExposureStarted':
      return SequencerEvent.exposureStarted(
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        filter: wireOptString(d, 'filter'),
        durationSecs: wireDouble(d, 'duration_secs'),
      );
    case 'ExposureCompleted':
      return SequencerEvent.exposureCompleted(
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        durationSecs: wireDouble(d, 'duration_secs'),
      );
    case 'MeridianFlipOutcome':
      return SequencerEvent.meridianFlipOutcome(
        outcome: wireRequired(decodeFlipOutcome(d['outcome']), 'outcome'),
        targetName: wireString(d, 'target_name'),
        newPierSide: wireString(d, 'new_pier_side'),
        durationSecs: wireDouble(d, 'duration_secs'),
        attempts: wireInt(d, 'attempts'),
        failedSteps: wireStringList(d, 'failed_steps'),
        error: wireOptString(d, 'error'),
        actionTaken: wireOptString(d, 'action_taken'),
      );
    case 'TriggerFired':
      return SequencerEvent.triggerFired(
        triggerId: wireString(d, 'trigger_id'),
        triggerName: wireString(d, 'trigger_name'),
        action: wireRequired(
          decodeSequencerTriggerAction(d['action']),
          'action',
        ),
      );
    case 'InstructionProgress':
      return SequencerEvent.instructionProgress(
        nodeId: wireString(d, 'node_id'),
        instruction: wireString(d, 'instruction'),
        progressPercent: wireDouble(d, 'progress_percent'),
        detail: wireString(d, 'detail'),
      );
    case 'InstructionProgressStructured':
      return SequencerEvent.instructionProgressStructured(
        nodeId: wireString(d, 'node_id'),
        instruction: wireString(d, 'instruction'),
        progressPercent: wireDouble(d, 'progress_percent'),
        detailKind: wireString(d, 'detail_kind'),
        detailJson: wireString(d, 'detail_json'),
      );
    case 'DepthGoalCompleted':
      return SequencerEvent.depthGoalCompleted(
        nodeId: wireString(d, 'node_id'),
        filterName: wireString(d, 'filter_name'),
        goalId: wireString(d, 'goal_id'),
        revision: wireBigInt(d, 'revision'),
        evidenceFrames: wireInt(d, 'evidence_frames'),
        confirmationFrames: wireInt(d, 'confirmation_frames'),
        score: wireDouble(d, 'score'),
        threshold: wireDouble(d, 'threshold'),
      );
    case 'FrameAccepted':
      return SequencerEvent.frameAccepted(
        nodeId: wireString(d, 'node_id'),
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        hfr: wireOptDouble(d, 'hfr'),
        eccentricity: wireOptDouble(d, 'eccentricity'),
        starCount: wireOptInt(d, 'star_count'),
        acceptedTotal: wireInt(d, 'accepted_total'),
        rejectedTotal: wireInt(d, 'rejected_total'),
        savePath: wireOptString(d, 'save_path'),
        capture: decodeFrameCaptureMetadata(d),
      );
    case 'FrameRejected':
      return SequencerEvent.frameRejected(
        nodeId: wireString(d, 'node_id'),
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        reason: wireString(d, 'reason'),
        hfr: wireOptDouble(d, 'hfr'),
        eccentricity: wireOptDouble(d, 'eccentricity'),
        starCount: wireOptInt(d, 'star_count'),
        rejectPath: wireString(d, 'reject_path'),
        consecutiveRejects: wireInt(d, 'consecutive_rejects'),
        acceptedTotal: wireInt(d, 'accepted_total'),
        rejectedTotal: wireInt(d, 'rejected_total'),
        likelyCauseLabel: wireOptString(d, 'likely_cause_label'),
        evidence: wireStringList(d, 'evidence'),
        skyBrightnessAtCapture: wireOptDouble(d, 'sky_brightness_at_capture'),
        cloudCoverAtCapture: wireOptDouble(d, 'cloud_cover_at_capture'),
        windAtCapture: wireOptDouble(d, 'wind_at_capture'),
        guideRmsAtCapture: wireOptDouble(d, 'guide_rms_at_capture'),
        sensorTempAtCapture: wireOptDouble(d, 'sensor_temp_at_capture'),
        capture: decodeFrameCaptureMetadata(d),
      );
    case 'SchedulerDecision':
      return SequencerEvent.schedulerDecision(
        nodeId: wireString(d, 'node_id'),
        decisionCounter: wireInt(d, 'decision_counter'),
        pickedTargetId: wireOptString(d, 'picked_target_id'),
        pickedTargetName: wireOptString(d, 'picked_target_name'),
        pickedScore: wireOptDouble(d, 'picked_score'),
        scores: wireMapList(
          d,
          'scores',
        ).map(decodeSchedulerScoreEntry).toList(),
      );
    case 'IntegrationBudget':
      return SequencerEvent.integrationBudget(
        targetId: wireString(d, 'target_id'),
        filter: wireString(d, 'filter'),
        completedSecs: wireDouble(d, 'completed_secs'),
        budgetSecs: wireDouble(d, 'budget_secs'),
        fraction: wireDouble(d, 'fraction'),
        budgetMet: wireBool(d, 'budget_met'),
      );
    case 'ExposureAdjusted':
      return SequencerEvent.exposureAdjusted(
        nodeId: wireString(d, 'node_id'),
        adaptedSecs: wireDouble(d, 'adapted_secs'),
        nominalSecs: wireDouble(d, 'nominal_secs'),
        skyBrightnessMag: wireOptDouble(d, 'sky_brightness_mag'),
        filter: wireOptString(d, 'filter'),
        reason: wireString(d, 'reason'),
      );
    case 'PhotometryFrame':
      return SequencerEvent.photometryFrame(
        nodeId: wireString(d, 'node_id'),
        targetDesignation: wireString(d, 'target_designation'),
        referenceStars: wireStringList(d, 'reference_stars'),
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        filter: wireString(d, 'filter'),
        exposureSecs: wireDouble(d, 'exposure_secs'),
        airmass: wireOptDouble(d, 'airmass'),
        fwhmArcsec: wireOptDouble(d, 'fwhm_arcsec'),
        snr: wireOptDouble(d, 'snr'),
        mjdObs: wireDouble(d, 'mjd_obs'),
        frameStartUnix: wireDouble(d, 'frame_start_unix'),
        accepted: wireBool(d, 'accepted'),
        rejectReason: wireOptString(d, 'reject_reason'),
        reduceLive: wireBool(d, 'reduce_live'),
        applyDifferential: wireBool(d, 'apply_differential'),
      );
    case 'PhotometryCadenceBroken':
      return SequencerEvent.photometryCadenceBroken(
        nodeId: wireString(d, 'node_id'),
        frame: wireInt(d, 'frame'),
        total: wireInt(d, 'total'),
        gapSecs: wireDouble(d, 'gap_secs'),
        maxGapSecs: wireDouble(d, 'max_gap_secs'),
        cadenceBreaks: wireInt(d, 'cadence_breaks'),
      );
    case 'PhotometrySummary':
      return SequencerEvent.photometrySummary(
        nodeId: wireString(d, 'node_id'),
        targetDesignation: wireString(d, 'target_designation'),
        filter: wireString(d, 'filter'),
        framesCaptured: wireInt(d, 'frames_captured'),
        cadenceBreaks: wireInt(d, 'cadence_breaks'),
        lastRejectReason: wireOptString(d, 'last_reject_reason'),
      );
    case 'RecoveryStarted':
      return SequencerEvent.recoveryStarted(
        startedAtIso: wireString(d, 'started_at_iso'),
        causeKind: wireString(d, 'cause_kind'),
        causeCustomLabel: wireOptString(d, 'cause_custom_label'),
        lastAttemptAtIso: wireOptString(d, 'last_attempt_at_iso'),
        attemptCount: wireInt(d, 'attempt_count'),
        maxAttempts: wireInt(d, 'max_attempts'),
        retryIntervalSecs: wireDouble(d, 'retry_interval_secs'),
        maxDurationSecs: wireDouble(d, 'max_duration_secs'),
        phase: wireString(d, 'phase'),
        lastError: wireOptString(d, 'last_error'),
      );
    case 'RecoveryProgress':
      return SequencerEvent.recoveryProgress(
        startedAtIso: wireString(d, 'started_at_iso'),
        causeKind: wireString(d, 'cause_kind'),
        causeCustomLabel: wireOptString(d, 'cause_custom_label'),
        lastAttemptAtIso: wireOptString(d, 'last_attempt_at_iso'),
        attemptCount: wireInt(d, 'attempt_count'),
        maxAttempts: wireInt(d, 'max_attempts'),
        retryIntervalSecs: wireDouble(d, 'retry_interval_secs'),
        maxDurationSecs: wireDouble(d, 'max_duration_secs'),
        phase: wireString(d, 'phase'),
        lastError: wireOptString(d, 'last_error'),
      );
    case 'RecoveryCompleted':
      return SequencerEvent.recoveryCompleted(
        startedAtIso: wireString(d, 'started_at_iso'),
        causeKind: wireString(d, 'cause_kind'),
        causeCustomLabel: wireOptString(d, 'cause_custom_label'),
        lastAttemptAtIso: wireOptString(d, 'last_attempt_at_iso'),
        attemptCount: wireInt(d, 'attempt_count'),
        maxAttempts: wireInt(d, 'max_attempts'),
        retryIntervalSecs: wireDouble(d, 'retry_interval_secs'),
        maxDurationSecs: wireDouble(d, 'max_duration_secs'),
        phase: wireString(d, 'phase'),
        lastError: wireOptString(d, 'last_error'),
      );
    case 'RecoveryGaveUp':
      return SequencerEvent.recoveryGaveUp(
        startedAtIso: wireString(d, 'started_at_iso'),
        causeKind: wireString(d, 'cause_kind'),
        causeCustomLabel: wireOptString(d, 'cause_custom_label'),
        lastAttemptAtIso: wireOptString(d, 'last_attempt_at_iso'),
        attemptCount: wireInt(d, 'attempt_count'),
        maxAttempts: wireInt(d, 'max_attempts'),
        retryIntervalSecs: wireDouble(d, 'retry_interval_secs'),
        maxDurationSecs: wireDouble(d, 'max_duration_secs'),
        phase: wireString(d, 'phase'),
        lastError: wireOptString(d, 'last_error'),
        abortedByUser: wireBool(d, 'aborted_by_user'),
      );
    case 'PluginNodeRequested':
      return SequencerEvent.pluginNodeRequested(
        nodeId: wireString(d, 'node_id'),
        pluginId: wireString(d, 'plugin_id'),
        nodeTypeId: wireString(d, 'node_type_id'),
        configJson: wireString(d, 'config_json'),
        displayName: wireOptString(d, 'display_name'),
        timeoutSecs: wireInt(d, 'timeout_secs'),
      );
    case 'PluginNodeProgress':
      return SequencerEvent.pluginNodeProgress(
        nodeId: wireString(d, 'node_id'),
        pluginId: wireString(d, 'plugin_id'),
        nodeTypeId: wireString(d, 'node_type_id'),
        detailJson: wireString(d, 'detail_json'),
      );
  }
  return null;
}

WireEvent _encodeSafetyEvent(SafetyEvent event) => switch (event) {
  SafetyEvent_WeatherUnsafe() => (
    'WeatherUnsafe',
    <String, Object?>{'reason': event.reason},
  ),
  SafetyEvent_WeatherSafe() => ('WeatherSafe', <String, Object?>{}),
  SafetyEvent_EmergencyStop() => (
    'EmergencyStop',
    <String, Object?>{'reason': event.reason},
  ),
  SafetyEvent_ParkInitiated() => (
    'ParkInitiated',
    <String, Object?>{'reason': event.reason},
  ),
  SafetyEvent_ParkCompleted() => ('ParkCompleted', <String, Object?>{}),
  SafetyEvent_MountMotionFault() => (
    'MountMotionFault',
    <String, Object?>{
      'device_id': event.deviceId,
      'kind': event.kind,
      'message': event.message,
    },
  ),
  SafetyEvent_MountPositionUnknown() => (
    'MountPositionUnknown',
    <String, Object?>{
      'device_id': event.deviceId,
      'reason': event.reason,
      'message': event.message,
    },
  ),
  SafetyEvent_MountGuardCleared() => (
    'MountGuardCleared',
    <String, Object?>{'device_id': event.deviceId, 'message': event.message},
  ),
};

SafetyEvent? _decodeSafetyEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'WeatherUnsafe':
      return SafetyEvent.weatherUnsafe(reason: wireString(d, 'reason'));
    case 'WeatherSafe':
      return const SafetyEvent.weatherSafe();
    case 'EmergencyStop':
      return SafetyEvent.emergencyStop(reason: wireString(d, 'reason'));
    case 'ParkInitiated':
      return SafetyEvent.parkInitiated(reason: wireString(d, 'reason'));
    case 'ParkCompleted':
      return const SafetyEvent.parkCompleted();
    case 'MountMotionFault':
      return SafetyEvent.mountMotionFault(
        deviceId: wireString(d, 'device_id'),
        kind: wireString(d, 'kind'),
        message: wireString(d, 'message'),
      );
    case 'MountPositionUnknown':
      return SafetyEvent.mountPositionUnknown(
        deviceId: wireString(d, 'device_id'),
        reason: wireString(d, 'reason'),
        message: wireString(d, 'message'),
      );
    case 'MountGuardCleared':
      return SafetyEvent.mountGuardCleared(
        deviceId: wireString(d, 'device_id'),
        message: wireString(d, 'message'),
      );
  }
  return null;
}

WireEvent _encodeSystemEvent(SystemEvent event) => switch (event) {
  SystemEvent_Initialized() => ('Initialized', <String, Object?>{}),
  SystemEvent_ShuttingDown() => ('ShuttingDown', <String, Object?>{}),
  SystemEvent_Error() => ('Error', <String, Object?>{'message': event.message}),
  SystemEvent_DiskSpaceLow() => (
    'DiskSpaceLow',
    <String, Object?>{'available_gb': event.availableGb},
  ),
  SystemEvent_Notification() => (
    'Notification',
    <String, Object?>{
      'title': event.title,
      'message': event.message,
      'level': event.level,
      if (event.explicitTransports != null)
        'explicit_transports': event.explicitTransports,
    },
  ),
  SystemEvent_EventsDropped() => (
    'EventsDropped',
    <String, Object?>{
      'dropped_count': event.droppedCount.toInt(),
      'total_dropped': event.totalDropped.toInt(),
    },
  ),
};

SystemEvent? _decodeSystemEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'Initialized':
      return const SystemEvent.initialized();
    case 'ShuttingDown':
      return const SystemEvent.shuttingDown();
    case 'Error':
      return SystemEvent.error(message: wireString(d, 'message'));
    case 'DiskSpaceLow':
      return SystemEvent.diskSpaceLow(
        availableGb: wireDouble(d, 'available_gb'),
      );
    case 'Notification':
      return SystemEvent.notification(
        title: wireString(d, 'title'),
        message: wireString(d, 'message'),
        level: wireString(d, 'level'),
        explicitTransports: wireOptStringList(d, 'explicit_transports'),
      );
    case 'EventsDropped':
      return SystemEvent.eventsDropped(
        droppedCount: wireBigInt(d, 'dropped_count'),
        totalDropped: wireBigInt(d, 'total_dropped'),
      );
  }
  return null;
}

WireEvent _encodeDepthLockEvent(DepthLockEvent event) => switch (event) {
  DepthLockEvent_GoalUpdated() => (
    'DepthLockGoalUpdated',
    <String, Object?>{
      'goal_id': event.goalId,
      'revision': event.revision.toInt(),
      'filter_name': event.filterName,
      'state': event.state,
      'score': event.score,
      'conservative_score': event.conservativeScore,
      'threshold': event.threshold,
      'uncertainty_adu': event.uncertaintyAdu,
      'coverage': event.coverage,
      'evidence_frames': event.evidenceFrames,
      'confirmation_frames': event.confirmationFrames,
      'reason': event.reason,
      'automatic_completion': event.automaticCompletion,
      'framesRemaining': event.framesRemaining,
      'reachable': event.reachable,
    },
  ),
  DepthLockEvent_EvidenceRejected() => (
    'DepthLockEvidenceRejected',
    <String, Object?>{
      'goal_id': event.goalId,
      'revision': event.revision.toInt(),
      'source_path': event.sourcePath,
      'reason': event.reason,
    },
  ),
  DepthLockEvent_AnalysisDropped() => (
    'DepthLockAnalysisDropped',
    <String, Object?>{'source_path': event.sourcePath, 'reason': event.reason},
  ),
  DepthLockEvent_GoalChanged() => (
    'DepthLockGoalChanged',
    <String, Object?>{
      'goal_id': event.goalId,
      'revision': event.revision.toInt(),
      'change': event.change,
    },
  ),
};

DepthLockEvent? _decodeDepthLockEvent(
  String type,
  Map<String, Object?> d,
  EventSeverity severity,
) {
  switch (type) {
    case 'DepthLockGoalUpdated':
      return DepthLockEvent.goalUpdated(
        goalId: wireString(d, 'goal_id'),
        revision: wireBigInt(d, 'revision'),
        filterName: wireString(d, 'filter_name'),
        state: wireString(d, 'state'),
        score: wireOptDouble(d, 'score'),
        conservativeScore: wireOptDouble(d, 'conservative_score'),
        threshold: wireDouble(d, 'threshold'),
        uncertaintyAdu: wireOptDouble(d, 'uncertainty_adu'),
        coverage: wireDouble(d, 'coverage'),
        evidenceFrames: wireInt(d, 'evidence_frames'),
        confirmationFrames: wireInt(d, 'confirmation_frames'),
        reason: wireString(d, 'reason'),
        automaticCompletion: wireBool(d, 'automatic_completion'),
        framesRemaining: wireOptInt(d, 'framesRemaining'),
        reachable: wireBool(d, 'reachable'),
      );
    case 'DepthLockEvidenceRejected':
      return DepthLockEvent.evidenceRejected(
        goalId: wireString(d, 'goal_id'),
        revision: wireBigInt(d, 'revision'),
        sourcePath: wireString(d, 'source_path'),
        reason: wireString(d, 'reason'),
      );
    case 'DepthLockAnalysisDropped':
      return DepthLockEvent.analysisDropped(
        sourcePath: wireString(d, 'source_path'),
        reason: wireString(d, 'reason'),
      );
    case 'DepthLockGoalChanged':
      return DepthLockEvent.goalChanged(
        goalId: wireString(d, 'goal_id'),
        revision: wireBigInt(d, 'revision'),
        change: wireString(d, 'change'),
      );
  }
  return null;
}

